import { createRemoteJWKSet, jwtVerify } from 'jose';
const JWKS = createRemoteJWKSet(new URL('https://login.acme.com/.well-known/jwks.json'), {
  cacheMaxAge: 10 * 60 * 1000,   // 10 min
  cooldownDuration: 30 * 1000     // min time between refetches on unknown kid
});
const { payload } = await jwtVerify(token, JWKS, {
  issuer: 'https://login.acme.com', audience: 'https://api.acme.com', algorithms: ['ES256']
});
